mapper.insert:
INSERT IGNORE INTO campaign_reservation(
  order_id, campaign_id, user_id, generation, request_key, state
) VALUES (
  #{orderId}, #{campaignId}, #{userId}, #{generation}, #{requestKey}, 'PROCESSING'
)

mapper.select:
SELECT * FROM campaign_reservation
WHERE campaign_id = #{campaignId} AND user_id = #{userId}
  AND request_key = #{requestKey}
ORDER BY order_id DESC
LIMIT 1

mapper.update:
UPDATE campaign_reservation
SET state = 'REVIEW', last_error = #{reason}
WHERE order_id = #{orderId} AND state = 'PROCESSING'

UPDATE campaign_reservation
SET state = 'FAILED', last_error = #{reason}
WHERE order_id = #{orderId} AND state IN ('PROCESSING','REVIEW')

UPDATE campaign_reservation
SET attempts = attempts + 1, last_error = #{reason}
WHERE order_id = #{orderId} AND state = 'PROCESSING'

mapper.select:
SELECT COUNT(*) FROM campaign_reservation
WHERE state IN ('PROCESSING','REVIEW')

  AND campaign_id = #{campaignId}
